window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b4e330217605cb03"]={"versions": [{"id": "FIG-b4e330217605cb03", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Prozess- und Anforderungs-Mapping-Diagramm (Traceability- / Methodik-Matrix) zur Gegenüberstellung des ISO-26262:2018-Sicherheitslebenszyklus und der Dokumentenstruktur von <code>AUTOSAR_EXP_SafetyOverview</code>.\n</li><li><strong>Technischer Zweck &amp; funktionale Einordnung:</strong> Das Dokument dient als sicherheitsbezogene Leitlinie (Explanation) für die AUTOSAR Adaptive Platform (AP) als Safety Element out of Context (SEooC). Das Diagramm verortet die hierarchische Dekomposition von Sicherheitsanforderungen (vom Safety Goal bis zu SW-Anforderungen der Functional Cluster) entlang der ISO-26262-Phasen und bildet die normativen Klauseln auf die Kapitel von <code>EXP_SafetyOverview</code> ab.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich vertikal in Lebenszyklusphasen und horizontal in zwei korrespondierende Säulen:</p>\n<ul class=\"fig-list\"><li><strong>Lebenszyklusphasen (ISO 26262 Prozessachse links):</strong>\n<ul class=\"fig-list\"><li><code>Concept Phase</code> (ISO 26262-3)\n</li><li><code>Product Development</code> (ISO 26262-4 für Systemebene, ISO 26262-6 für Softwareebene)\n</li><li><code>After release for production</code> (ISO 26262-7; als nachfolgende Phase ohne direkte Mapping-Kapitel im Dokument dargestellt)\n</li></ul>\n</li><li><strong>Entitäten der ISO 26262:2018 (Normative Artefakte / Aktivitäten links):</strong>\n<ol class=\"fig-list\"><li><em>Klausel 3-7 (Hazard Analysis and Risk Assessment):</em> Gefahrenanalyse und Risikobewertung (HARA).\n</li><li><em>Klausel 3-7 (Specification of Safety Goals):</em> Definition der Sicherheitsziele mit zugewiesenem ASIL.\n</li><li><em>Klausel 3-8 (Functional Safety Concept):</em> Definition (<code>Specification</code>) und Allokation (<code>Allocation</code>) der funktionalen Sicherheitsanforderungen (FSR).\n</li><li><em>Klausel 4-6 (Specification of Technical Safety Concept):</em> Definition (<code>Specification</code>) und Allokation (<code>Allocation</code>) der technischen Sicherheitsanforderungen (TSR) auf Systemebene.\n</li><li><em>Klausel 6-6 (Specification of Software Safety Requirements):</em> Definition der Software-Sicherheitsanforderungen (SSR).\n</li></ol>\n</li><li><strong>Entitäten der AUTOSAR Adaptive Platform (<code>EXP_Safety_Overview</code> rechts):</strong>\n<ol class=\"fig-list\"><li><em>Chapter 4 – Hazard Analysis:</em> Analyse generischer Gefährdungen im Kontext der Adaptive Platform als SEooC.\n</li><li><em>Chapter 5 – Specification of Top Level Safety Requirements:</em> Ableitung und Formulierung von übergeordneten Sicherheitsanforderungen (analog zu Safety Goals auf Plattformebene).\n</li><li><em>Chapter 6 – Specification &amp; Allocation of Functional Safety Requirements:</em> Funktionale Sicherheitsanforderungen und deren Zuordnung zu architektonischen Funktionselementen.\n</li><li><em>Chapter 7 – Specification &amp; Allocation of Technical Safety Requirements:</em> Technische Sicherheitsanforderungen und Allokation auf System-/Architekturebene der AP.\n</li><li><em>Chapter 8 – Listing of Functional-Cluster Software Requirements:</em> Granulare SW-Sicherheitsanforderungen für spezifische Functional Cluster (z. B. Execution Management, State Management, ara::com, IAM, Platform Health Management).\n</li></ol>\n</li><li><strong>Strukturelle Beziehungen:</strong>\n<ul class=\"fig-list\"><li>1:1-Mapping der normativen Sicherheitsartefakte auf die Kapitelstruktur der Spezifikation.\n</li><li>Streng hierarchische Top-Down-Dekomposition: Safety Goals → FSR → TSR → SSR.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet keinen Laufzeit-Kontrollfluss ab, sondern einen <strong>statischen Phasen- und Dekompositionsablauf</strong> im Engineering-Prozess:</p>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Definition des Fahrzeug-Items bzw. des Plattform-Scopes (SEooC Assumption of Use).\n</li><li><strong>Phase 1 (HARA):</strong> ISO 3-7 / Kap. 4 identifiziert Gefährdungsszenarien und bestimmt ASIL-Einstufungen.\n</li><li><strong>Phase 2 (Top-Level Requirements):</strong> ISO 3-7 / Kap. 5 definiert Sicherheitsziele (Safety Goals) bzw. Top-Level Safety Requirements der Plattform.\n</li><li><strong>Phase 3 (Funktionales Sicherheitskonzept - FSC):</strong> ISO 3-8 / Kap. 6 leitet FSR ab und allokiert diese auf funktionale Einheiten (Fehlererkennung, Übergang in sicheren Zustand).\n</li><li><strong>Phase 4 (Technisches Sicherheitskonzept - TSC):</strong> ISO 4-6 / Kap. 7 transformiert FSR in hardware- und softwareunabhängige/-spezifische TSR (z. B. Zeitüberwachung, Speicherschutz, redundante Pfade).\n</li><li><strong>Phase 5 (SW-Entwicklung):</strong> ISO 6-6 / Kap. 8 bricht TSR herunter auf die Anforderungen der AP Functional Cluster (Basis für die jeweiligen SWS-Dokumente wie <code>SWS_ExecutionManagement</code>, <code>SWS_CommunicationManagement</code>).\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>SEooC-Integration (ISO 26262-10):</strong> Entwickler von Adaptive Applications (AA) und Plattform-Integratoren dürfen <code>EXP_SafetyOverview</code> nicht als vollständigen Sicherheitsnachweis missverstehen. Da die Adaptive Platform ein SEooC ist, müssen OEM/Tier-1 die in Kapitel 4 und 5 getroffenen Annahmen (<em>Assumptions of Use</em>, AoU) mit der konkreten Fahrzeug-HARA abgleichen.\n</li><li><strong>Traceability-Kette:</strong> Anforderungen in Kapitel 8 verlinken direkt in die normativen Spezifikationen der Functional Cluster (<code>SWS_*</code>). Sicherheitsrelevante Cluster (z. B. PHM – <em>Platform Health Management</em> zur Überwachung von Deadlines, logischen Programmabläufen und Alive-Signalen) leiten ihre ASIL-Fähigkeit direkt aus der Kette Kap. 6 → Kap. 7 → Kap. 8 ab.\n</li><li><strong>Entwickler-Konsequenzen (ara-Stack / Applikation):</strong>\n<ul class=\"fig-list\"><li><em>Freedom from Interference (FFI):</em> Einhaltung der in Kap. 7/8 definierten Mechanismen für räumliche (Memory Protection via OS/MMU) und zeitliche Separation (Scheduling via Execution Management).\n</li><li><em>Sicherheitsmuster:</em> Bei Implementierung von Applikationen mit Sicherheitsrelevanz (ASIL B bis ASIL D) müssen Entwickler prüfen, welche Sicherheitsmechanismen (z. B. E2E-Protection in <code>ara::com</code>, SM-Zustandswechsel) durch die Plattform bereitgestellt werden und welche Sicherheitsanforderungen auf die Applikation rückallokiert sind.\n</li></ul>\n</li></ul>"}, {"id": "FIG-927a94a4095e57bc", "releases": ["R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Prozess- und Anforderungs-Mapping-Diagramm (Traceability- / Methodik-Matrix) zur Gegenüberstellung des ISO-26262:2018-Sicherheitslebenszyklus und der Dokumentenstruktur von <code>AUTOSAR_EXP_SafetyOverview</code>.\n</li><li><strong>Technischer Zweck &amp; funktionale Einordnung:</strong> Das Dokument dient als sicherheitsbezogene Leitlinie (Explanation) für die AUTOSAR Adaptive Platform (AP) als Safety Element out of Context (SEooC). Das Diagramm verortet die hierarchische Dekomposition von Sicherheitsanforderungen (vom Safety Goal bis zu SW-Anforderungen der Functional Cluster) entlang der ISO-26262-Phasen und bildet die normativen Klauseln auf die Kapitel von <code>EXP_SafetyOverview</code> ab.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich vertikal in Lebenszyklusphasen und horizontal in zwei korrespondierende Säulen:</p>\n<ul class=\"fig-list\"><li><strong>Lebenszyklusphasen (ISO 26262 Prozessachse links):</strong>\n<ul class=\"fig-list\"><li><code>Concept Phase</code> (ISO 26262-3)\n</li><li><code>Product Development</code> (ISO 26262-4 für Systemebene, ISO 26262-6 für Softwareebene)\n</li><li><code>after release for production</code> (ISO 26262-7; als nachfolgende Phase ohne direkte Mapping-Kapitel im Dokument dargestellt)\n</li></ul>\n</li><li><strong>Entitäten der ISO 26262:2018 (Normative Artefakte / Aktivitäten links):</strong>\n<ol class=\"fig-list\"><li><em>Klausel 3-6 (Hazard Analysis and Risk Assessment):</em> Gefahrenanalyse und Risikobewertung (HARA).\n</li><li><em>Klausel 3-6 (Hazard Analysis and Risk Assessment / Specification of Safety Goals):</em> Definition der Sicherheitsziele mit zugewiesenem ASIL.\n</li><li><em>Klausel 3-7 (Functional Safety Concept):</em> Definition (<code>Specification</code>) und Allokation (<code>Allocation</code>) der funktionalen Sicherheitsanforderungen (FSR).\n</li><li><em>Klausel 4-6 (Technical Safety Concept):</em> Definition (<code>Specification</code>) und Allokation (<code>Allocation</code>) der technischen Sicherheitsanforderungen (TSR) auf Systemebene.\n</li><li><em>Klausel 6-6 (Specification of Software Safety Requirements):</em> Definition der Software-Sicherheitsanforderungen (SSR).\n</li></ol>\n</li><li><strong>Entitäten der AUTOSAR Adaptive Platform (<code>EXP_SafetyOverview</code> rechts):</strong>\n<ol class=\"fig-list\"><li><em>Chapter 4 – Hazards and Malfunctions:</em> Analyse generischer Fehlfunktionen und Gefährdungen im Kontext der Adaptive Platform als SEooC.\n</li><li><em>Chapter 5 – Specification of Safety Goals:</em> Definition und Formulierung von Sicherheitszielen (Safety Goals) auf Plattformebene.\n</li><li><em>Chapter 6 – Specification of Functional Safety Requirements / Allocation of Functional Safety Requirements:</em> Funktionale Sicherheitsanforderungen und deren Allokation.\n</li><li><em>Chapter 7 – Specification of Technical Safety Requirements / Allocation of Technical Safety Requirements:</em> Technische Sicherheitsanforderungen und Allokation auf Plattformarchitekturebene.\n</li><li><em>Chapter 8 – Listing of Functional-Cluster Software Requirements:</em> Granulare SW-Sicherheitsanforderungen für spezifische Functional Cluster.\n</li></ol>\n</li><li><strong>Strukturelle Beziehungen:</strong>\n<ul class=\"fig-list\"><li>1:1-Mapping der normativen ISO-26262-Sicherheitsartefakte auf die Kapitelstruktur der Spezifikation.\n</li><li>Vertikale Dekomposition über gerichtete Pfeile entlang der V-Modell-Hierarchie: HARA → Safety Goals → Functional Safety Concept → Technical Safety Concept → Software Safety Requirements.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet keinen Laufzeit-Kontrollfluss ab, sondern einen <strong>statischen Phasen- und Dekompositionsablauf</strong> im Engineering-Prozess:</p>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Definition des Systemkontexts und Plattform-Scopes (SEooC Assumption of Use).\n</li><li><strong>Concept Phase (ISO 26262-3):</strong>\n<ul class=\"fig-list\"><li>Schritt 1: Durchführung von HARA bzw. Analyse von Fehlfunktionen (ISO 3-6 ↔ Chapter 4).\n</li><li>Schritt 2: Spezifikation der Safety Goals (ISO 3-6 ↔ Chapter 5).\n</li><li>Schritt 3: Ableitung und Allokation der Functional Safety Requirements im Functional Safety Concept (ISO 3-7 ↔ Chapter 6).\n</li></ul>\n</li><li><strong>Übergang Phase 1 → Phase 2:</strong> Gestrichelte Trennlinie markiert den Meilenstein zur Produktentwicklung.\n</li><li><strong>Product Development (ISO 26262-4 &amp; ISO 26262-6):</strong>\n<ul class=\"fig-list\"><li>Schritt 4: Spezifikation und Allokation der Technical Safety Requirements im Technical Safety Concept auf Systemebene (ISO 4-6 ↔ Chapter 7).\n</li><li>Schritt 5: Ableitung der Software Safety Requirements für die Software-Implementierung (ISO 6-6 ↔ Chapter 8).\n</li></ul>\n</li><li><strong>After release for production (ISO 26262-7):</strong> Nachgelagerte Lebenszyklusphase, für die innerhalb dieses Dokuments keine Spezifikationskapitel ausgewiesen sind.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Standard-Konformität:</strong> Basiert auf ISO 26262:2018 (Teile 3, 4, 6 und 7). Die Klauselnummern korrespondieren mit der Zählung der Ausgabe 2018 (z. B. Part 3 Clause 6 für HARA, Part 3 Clause 7 für FSC, Part 4 Clause 6 für TSC, Part 6 Clause 6 für SSR).\n</li><li><strong>Rolle als SEooC:</strong> Die Adaptive Platform wird als Safety Element out of Context entwickelt; die in Kapitel 4 bis 8 definierten Anforderungen dienen Systemintegratoren zur Verifikation gegen ihre fahrzeugspezifischen Item-Definitionen und Safety Goals.\n</li><li><strong>Traceability:</strong> Das Mapping stellt eine lückenlose Rückverfolgbarkeit von den Sicherheitszielen über funktionale und technische Anforderungen bis hin zu cluster-spezifischen Softwareanforderungen sicher.\n</li></ul>"}], "trans": [{"from": "FIG-b4e330217605cb03", "to": "FIG-927a94a4095e57bc", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Kopfzeile der rechten Spalte: Dokumenttitel von <code>EXP_Safety_Overview</code> zu <code>EXP_SafetyOverview</code> korrigiert.\n</li><li>ISO-26262-Klauseln (linke Spalte):\n<ul class=\"fig-list\"><li>HARA und Safety Goals von <code>3-7</code> auf <code>3-6 Hazard Analysis and Risk Assessment</code> korrigiert.\n</li><li>Functional Safety Concept von <code>3-8</code> auf <code>3-7 Functional Safety Concept</code> korrigiert.\n</li><li>Technical Safety Concept von <code>4-6 Specification of Technical Safety Concept</code> auf <code>4-6 Technical Safety Concept</code> verkürzt.\n</li></ul>\n</li><li>Kapitelbezeichnungen der Adaptive Platform (rechte Spalte):\n<ul class=\"fig-list\"><li>Chapter 4: Umbenennung von <code>Hazard Analysis</code> zu <code>Hazards and Malfunctions</code>.\n</li><li>Chapter 5: Umbenennung von <code>Specification of Top Level Safety Requirements</code> zu <code>Specification of Safety Goals</code>.\n</li></ul>\n</li></ul>"}]};
